// The DOM is only a compositor for these pixels. Ink geometry and coverage are
// generated by native Xournal++/Cairo code, not Canvas/Skia paths.
const nativeInkStatus=window.desktop?.inkStatus?.()||null;
let nativePenReady=!!nativeInkStatus?.hooks,nativeInkFrame=null;
let pendingBrowserPen=[],browserPenTimer=null,browserPenFallback=false,nativeContact=false;
let consumeNativePackets=()=>{};
const hasNativeInk=()=>!!nativeInkStatus?.cairo;
function duplicateBrowserPen(e){
  if(!nativePenReady||e.pointerType!=='pen'||e.nativeInk||e.nativeFallback)return false;
  if(browserPenFallback){if(e.type==='pointerup'||e.type==='pointercancel')browserPenFallback=false;return false}
  if(nativeContact)return true;
  if(e.type==='pointerdown'){
    pendingBrowserPen=[];clearTimeout(browserPenTimer);
    // Some tablet drivers expose only legacy mouse/browser events. Give native
    // packets priority, but never make such a pen silently stop working.
    browserPenTimer=setTimeout(()=>{
      browserPenTimer=null;if(nativeContact){pendingBrowserPen=[];return}
      browserPenFallback=true;const queued=pendingBrowserPen;pendingBrowserPen=[];
      const badge=document.querySelector('#native-ink-status');if(badge)badge.textContent='原生绘制 · 笔输入回退（未收到 Windows 笔数据）';
      for(const {event,target} of queued){target.dispatchEvent(event);if(event.type==='pointerup'||event.type==='pointercancel')browserPenFallback=false}
    },24);
  }
  if(browserPenTimer!==null){
    const clone=new PointerEvent(e.type,{bubbles:true,pointerId:e.pointerId,pointerType:'pen',clientX:e.clientX,clientY:e.clientY,pressure:e.pressure,button:e.button,buttons:e.buttons,width:e.width,height:e.height});
    const samples=e.getCoalescedEvents?.()||[];
    Object.defineProperties(clone,{nativeFallback:{value:true},timeStamp:{value:e.timeStamp},getCoalescedEvents:{value:()=>samples}});
    pendingBrowserPen.push({event:clone,target:e.target});
  }
  return true;
}
function nativePoints(s){const data=new Float64Array(s.points.length*3);for(let i=0;i<s.points.length;i++){const p=s.points[i];data[i*3]=p.x;data[i*3+1]=p.y;data[i*3+2]=p.p}return data}
function clippedInkRect(b){
  const x=Math.max(0,Math.floor(b.x)),y=Math.max(0,Math.floor(b.y));
  return{x,y,w:Math.max(0,Math.min(canvas.width,Math.ceil(b.x+b.w))-x),h:Math.max(0,Math.min(canvas.height,Math.ceil(b.y+b.h))-y)};
}
function cairoBitmap(s,b){
  const data=desktop.inkRaster({points:nativePoints(s),width:s.width,hasPressure:s.hasPressure!==false,color:parseInt(s.color.slice(1),16),pixelWidth:b.w,pixelHeight:b.h,scale:view.scale*surface.dpr,tx:(view.x+surface.padding)*surface.dpr-b.x,ty:(view.y+surface.padding)*surface.dpr-b.y});
  return new ImageData(new Uint8ClampedArray(data),b.w,b.h);
}
function paintCairoStroke(context,s){
  const cache=cachedStroke(s),key=inkTileSignature();
  if(cache.cairoKey!==key){
    cache.cairoKey=key;const b=clippedInkRect(screenBounds(s.points,s.width));cache.cairoBounds=b;cache.cairoCanvas=null;
    if(b.w&&b.h){const image=document.createElement('canvas');image.width=b.w;image.height=b.h;image.getContext('2d').putImageData(cairoBitmap(s,b),0,0);cache.cairoCanvas=image}
  }
  if(cache.cairoCanvas){context.save();context.setTransform(1,0,0,1,0,0);context.drawImage(cache.cairoCanvas,cache.cairoBounds.x,cache.cairoBounds.y);context.restore()}
}
function scheduleCairoInk(){if(nativeInkFrame===null)nativeInkFrame=requestAnimationFrame(()=>{nativeInkFrame=null;flushCairoInk()})}
function cancelCairoInk(){if(nativeInkFrame!==null)cancelAnimationFrame(nativeInkFrame);nativeInkFrame=null}
function flushCairoInk(){
  cancelCairoInk();if(active?.type!=='pen'||active.s.brush!=='xournal')return;
  const s=active.s,key=inkTileSignature();
  if(active.cairoKey!==key){active.cairoKey=key;active.cairoCursor=0;clearLayer(inkLayers[1]);clearLayer(inkLayers[2])}
  if(active.cairoCursor===s.points.length)return;
  // A newly appended point only changes the last join, cap and new segments.
  const b=clippedInkRect(screenBounds(s.points.slice(Math.max(0,active.cairoCursor-3)),s.width));
  if(b.w&&b.h)inkLayers[1].ctx.putImageData(cairoBitmap(s,b),b.x,b.y);
  active.cairoCursor=s.points.length;renderStats.livePaints++;
}
function startNativePenBridge(){
  if(!hasNativeInk())return;
  const badge=document.createElement('span');badge.id='native-ink-status';badge.textContent='原生笔迹';badge.title='Windows 高精度笔输入 · Xournal++ 压力轮廓 · Cairo';document.querySelector('.hint')?.append(document.createElement('br'),badge);
  const targets=new Map();
  consumeNativePackets=packets=>{
    for(const packet of packets){
      const samples=packet.samples;if(!samples.length)continue;const last=samples.at(-1),id=last.id;
      if(browserPenFallback)continue;
      const dpr=window.devicePixelRatio||1,coalesced=samples.map(p=>({clientX:p.x/dpr,clientY:p.y/dpr,pressure:p.p,pointerType:'pen',buttons:packet.type==='pointerup'?0:p.eraser?32:1}));
      const q=coalesced.at(-1);
      if(packet.type==='pointerdown'){
        const target=document.elementFromPoint(q.clientX,q.clientY);if(!target||!viewport.contains(target))continue;targets.set(id,target);
        clearTimeout(browserPenTimer);browserPenTimer=null;pendingBrowserPen=[];nativeContact=true;
        badge.textContent=last.precise?'原生高精度笔迹':'原生笔迹 · 设备仅提供像素坐标';
      }
      if(!targets.has(id))continue;
      // Native Windows IDs and Chromium touch IDs are different namespaces.
      const event=new PointerEvent(packet.type,{bubbles:true,pointerId:0x40000000+id,pointerType:'pen',button:last.eraser?5:0,buttons:q.buttons,clientX:q.clientX,clientY:q.clientY,pressure:q.pressure});
      Object.defineProperties(event,{nativeInk:{value:true},nativePrecision:{value:!!last.precise},getCoalescedEvents:{value:()=>coalesced}});
      (packet.type==='pointerdown'?targets.get(id):viewport).dispatchEvent(event);
      if(packet.type==='pointerup'||packet.type==='pointercancel'){targets.delete(id);nativeContact=false}
    }
  };
  desktop.onPen(consumeNativePackets);
  window.addEventListener('blur',()=>{targets.clear();nativeContact=false;browserPenFallback=false;clearTimeout(browserPenTimer);browserPenTimer=null;pendingBrowserPen=[]});
  // Child HWNDs can be created after the initial document has loaded.
  const timer=setInterval(()=>{const status=desktop.inkStatus();nativePenReady=!!status?.hooks;if(!nativePenReady)badge.textContent='原生绘制 · 笔输入未就绪'},1000);
  window.addEventListener('beforeunload',()=>clearInterval(timer),{once:true});
}
